import 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:mudra_manager/core/db/isar_service.dart';\nimport 'package:mudra_manager/core/db/models/transaction.dart';\nimport 'package:mudra_manager/core/db/models/budget.dart';\nimport 'package:mudra_manager/core/db/models/goal.dart';\nimport 'package:mudra_manager/core/db/models/recurring_transaction.dart';\nimport 'package:mudra_manager/features/statistics/data/financial_context_service.dart';\nimport 'package:mudra_manager/features/statistics/data/financial_signal_generator.dart';\nimport 'package:mudra_manager/features/statistics/data/contextual_scorer.dart';\nimport 'package:mudra_manager/features/statistics/data/financial_attention_layer.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\n\n/// Orchestrator provider that combines all context engine phases\nfinal adaptiveUtilityProvider = FutureProvider.autoDispose<AdaptiveUtilityState>((ref) async {\n  final isar = ref.watch(isarServiceProvider).database;\n  \n  // Phase 1: Compute financial context\n  final contextService = FinancialContextService(isar);\n  final context = await contextService.computeContext();\n  \n  // Only proceed if context is fresh and meaningful\n  if (!context.isContextFresh || context.monthlyIncomeEstimate == 0) {\n    return AdaptiveUtilityState.insufficient(context);\n  }\n  \n  // Get recent financial data\n  final last30Days = DateTime.now().subtract(const Duration(days: 30));\n  final transactions = await isar.transactions\n      .filter()\n      .timestampGreaterThan(last30Days)\n      .findAll();\n      \n  final budgets = await isar.budgets\n      .filter()\n      .isActiveEqualTo(true)\n      .findAll();\n      \n  final goals = await isar.goals\n      .filter()\n      .isActiveEqualTo(true)\n      .findAll();\n      \n  final recurringTransactions = await isar.recurringTransactions\n      .filter()\n      .isActiveEqualTo(true)\n      .findAll();\n  \n  // Phase 2: Generate financial signals\n  final signalGenerator = FinancialSignalGenerator();\n  final signals = signalGenerator.generateSignals(\n    recentTransactions: transactions,\n    budgets: budgets,\n    goals: goals,\n    bills: recurringTransactions,\n    context: context,\n  );\n  \n  // Phase 3: Score signals with context\n  final scorer = ContextualScorer();\n  \n  // Phase 4: Filter for attention\n  final attentionLayer = FinancialAttentionLayer(scorer);\n  final attentionItems = attentionLayer.filterForAttention(signals, context);\n  \n  // Check if system should remain silent\n  final shouldRemainSilent = attentionLayer.shouldRemainSilent(context, attentionItems);\n  \n  // Get usage patterns for adaptive ordering\n  final usagePatterns = await _getUsagePatterns();\n  \n  return AdaptiveUtilityState.ready(\n    context: context,\n    attentionItems: attentionItems,\n    shouldShowAdvisory: !shouldRemainSilent,\n    usagePatterns: usagePatterns,\n  );\n});\n\n/// Get utility usage patterns for adaptive ordering\nFuture<Map<String, UtilityUsage>> _getUsagePatterns() async {\n  final prefs = await SharedPreferences.getInstance();\n  \n  final patterns = <String, UtilityUsage>{};\n  \n  // Get usage data for each utility\n  for (final utilityId in _allUtilityIds) {\n    final openCount = prefs.getInt('utility_opens_$utilityId') ?? 0;\n    final lastOpened = prefs.getInt('utility_last_opened_$utilityId') ?? 0;\n    final lastOpenedDate = lastOpened > 0 \n        ? DateTime.fromMillisecondsSinceEpoch(lastOpened)\n        : null;\n    \n    patterns[utilityId] = UtilityUsage(\n      utilityId: utilityId,\n      openCount: openCount,\n      lastOpened: lastOpenedDate,\n      recentlyUsed: lastOpenedDate != null && \n                    DateTime.now().difference(lastOpenedDate).inDays <= 7,\n    );\n  }\n  \n  return patterns;\n}\n\n/// Track utility usage for adaptive learning\nfinal utilityTrackerProvider = Provider<UtilityTracker>((ref) {\n  return UtilityTracker();\n});\n\nclass UtilityTracker {\n  /// Track when user opens a utility\n  Future<void> trackUtilityOpen(String utilityId) async {\n    final prefs = await SharedPreferences.getInstance();\n    \n    final currentCount = prefs.getInt('utility_opens_$utilityId') ?? 0;\n    await prefs.setInt('utility_opens_$utilityId', currentCount + 1);\n    await prefs.setInt('utility_last_opened_$utilityId', \n                       DateTime.now().millisecondsSinceEpoch);\n  }\n  \n  /// Track task completion from advisory items\n  Future<void> trackTaskCompletion(String attentionItemId) async {\n    final prefs = await SharedPreferences.getInstance();\n    \n    final completions = prefs.getStringList('completed_tasks') ?? [];\n    completions.add('${attentionItemId}_${DateTime.now().millisecondsSinceEpoch}');\n    \n    // Keep only last 50 completions\n    if (completions.length > 50) {\n      completions.removeAt(0);\n    }\n    \n    await prefs.setStringList('completed_tasks', completions);\n  }\n}\n\n/// Adaptive utility state with context awareness\nclass AdaptiveUtilityState {\n  final UserFinancialContext context;\n  final List<AttentionItem> attentionItems;\n  final bool shouldShowAdvisory;\n  final Map<String, UtilityUsage> usagePatterns;\n  final AdaptiveMode mode;\n  \n  const AdaptiveUtilityState._({\n    required this.context,\n    required this.attentionItems,\n    required this.shouldShowAdvisory,\n    required this.usagePatterns,\n    required this.mode,\n  });\n  \n  factory AdaptiveUtilityState.ready({\n    required UserFinancialContext context,\n    required List<AttentionItem> attentionItems,\n    required bool shouldShowAdvisory,\n    required Map<String, UtilityUsage> usagePatterns,\n  }) {\n    return AdaptiveUtilityState._(\n      context: context,\n      attentionItems: attentionItems,\n      shouldShowAdvisory: shouldShowAdvisory,\n      usagePatterns: usagePatterns,\n      mode: AdaptiveMode.ready,\n    );\n  }\n  \n  factory AdaptiveUtilityState.insufficient(UserFinancialContext context) {\n    return AdaptiveUtilityState._(\n      context: context,\n      attentionItems: const [],\n      shouldShowAdvisory: false,\n      usagePatterns: const {},\n      mode: AdaptiveMode.insufficient,\n    );\n  }\n  \n  /// Get recommended utilities based on usage and context\n  List<String> getRecommendedUtilities() {\n    final recommendations = <_UtilityRecommendation>[];\n    \n    for (final utilityId in _allUtilityIds) {\n      final usage = usagePatterns[utilityId] ?? UtilityUsage.empty(utilityId);\n      final contextRelevance = _calculateContextRelevance(utilityId, context);\n      final usageScore = _calculateUsageScore(usage);\n      \n      final totalScore = contextRelevance * 0.7 + usageScore * 0.3;\n      \n      recommendations.add(_UtilityRecommendation(\n        utilityId: utilityId,\n        score: totalScore,\n        contextRelevance: contextRelevance,\n        usageScore: usageScore,\n      ));\n    }\n    \n    recommendations.sort((a, b) => b.score.compareTo(a.score));\n    return recommendations.map((r) => r.utilityId).toList();\n  }\n  \n  /// Calculate how relevant a utility is to current financial context\n  double _calculateContextRelevance(String utilityId, UserFinancialContext context) {\n    switch (utilityId) {\n      case 'recurring':\n        // Bills more relevant when liquidity is low or autopay coverage is low\n        return context.liquidityBufferDays < 15 ? 0.9 :\n               context.autopayCoverage < 0.5 ? 0.8 : 0.6;\n               \n      case 'budgets':\n        // Budgets more relevant when spending is volatile or buffer is low\n        return context.spendingVolatilityIndex > 0.4 ? 0.9 :\n               context.liquidityBufferDays < 30 ? 0.8 : 0.5;\n               \n      case 'goals':\n        // Goals more relevant when financially stable\n        return context.isStable ? 0.8 : 0.4;\n        \n      case 'credit_cards':\n        // Credit cards more relevant when debt ratio is high\n        return context.debtRatio > 0.3 ? 0.9 :\n               context.debtRatio > 0.1 ? 0.7 : 0.3;\n               \n      case 'trips':\n        // Trips less contextually dependent\n        return 0.5;\n        \n      case 'tax_estimation':\n        // Tax more relevant during filing season and for higher incomes\n        final month = DateTime.now().month;\n        final isTaxSeason = month >= 1 && month <= 3; // Jan-Mar\n        final hasSignificantIncome = context.monthlyIncomeEstimate > 50000;\n        return isTaxSeason && hasSignificantIncome ? 0.8 : 0.3;\n        \n      default:\n        return 0.5;\n    }\n  }\n  \n  /// Calculate usage-based score\n  double _calculateUsageScore(UtilityUsage usage) {\n    if (usage.openCount == 0) return 0.1;\n    \n    final recencyScore = usage.recentlyUsed ? 0.8 : 0.2;\n    final frequencyScore = (usage.openCount / 20.0).clamp(0.0, 1.0);\n    \n    return recencyScore * 0.6 + frequencyScore * 0.4;\n  }\n}\n\n/// Utility usage tracking\nclass UtilityUsage {\n  final String utilityId;\n  final int openCount;\n  final DateTime? lastOpened;\n  final bool recentlyUsed;\n  \n  const UtilityUsage({\n    required this.utilityId,\n    required this.openCount,\n    this.lastOpened,\n    required this.recentlyUsed,\n  });\n  \n  factory UtilityUsage.empty(String utilityId) {\n    return UtilityUsage(\n      utilityId: utilityId,\n      openCount: 0,\n      lastOpened: null,\n      recentlyUsed: false,\n    );\n  }\n}\n\nclass _UtilityRecommendation {\n  final String utilityId;\n  final double score;\n  final double contextRelevance;\n  final double usageScore;\n  \n  const _UtilityRecommendation({\n    required this.utilityId,\n    required this.score,\n    required this.contextRelevance,\n    required this.usageScore,\n  });\n}\n\nenum AdaptiveMode { ready, insufficient }\n\n// All utility IDs for tracking\nconst _allUtilityIds = [\n  'recurring',\n  'trips', \n  'credit_cards',\n  'budgets',\n  'goals',\n  'monthly_recap',\n  'monthly_comparison',\n  'tax_estimation',\n];\n\n// Re-export types from attention layer\nexport 'package:mudra_manager/features/statistics/data/financial_attention_layer.dart' \n    show AttentionItem, AttentionType;